def transform(grid):
    h, w = len(grid), len(grid[0])
    target = min(r for r, row in enumerate(grid) for value in row if value == 8)
    out = [[0] * w for _ in range(h)]
    for color in {v for row in grid for v in row if v != 0}:
        cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color]
        shift = target - min(r for r, _ in cells)
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = color
    return out
